using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BMStairs {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var old=player.transform.position;bool enabled=cc.enabled;var results=new List<object>();try{foreach(var center in new[]{new Vector3(-44,-34,28),new Vector3(44,-34,-28)}){var points=new List<Vector3>{new Vector3(-.96f,0,-2.35f)};for(int i=0;i<8;i++){float dir=i%2==0?1:-1,x=i%2==0?-.96f:.96f;points.Add(new Vector3(x,i*2,-1.755f*dir));points.Add(new Vector3(x,(i+1)*2,1.755f*dir));points.Add(new Vector3(x,(i+1)*2,2.45f*dir));if(i<7)points.Add(new Vector3(-x,(i+1)*2,2.45f*dir));}points.Add(new Vector3(0,16,-2.45f));points.Add(new Vector3(0,16,-3.85f));foreach(bool reverse in new[]{false,true}){var path=(reverse?points.AsEnumerable().Reverse():points).Select(p=>p+center).ToArray();cc.enabled=false;player.transform.position=path[0]+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();bool pass=true;float remain=0;int index=0;foreach(var target in path.Skip(1)){index++;int max=(int)(Vector3.Distance(player.transform.position,target)/.05f)+140;for(int i=0;i<max;i++){var d=target-player.transform.position;d.y=0;remain=d.magnitude;if(remain<.025f)break;cc.Move(d.normalized*Mathf.Min(.05f,remain)+Vector3.down*.045f);}if(remain>.08f){pass=false;break;}}for(int i=0;i<12;i++)cc.Move(Vector3.down*.035f);float feet=player.transform.position.y+cc.center.y-cc.height*.5f;float error=feet-path.Last().y;pass&=Mathf.Abs(error)<.3f;results.Add(new{core=center.x<0?"VA":"VB",reverse,passed=pass,index,remain,heightError=error,position=player.transform.position.ToString()});}}}finally{cc.enabled=false;player.transform.position=old;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/Review/2026-11-09_B2_FullFloor/stairs.json")),JsonConvert.SerializeObject(results,Formatting.Indented));return results;}
}
